using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Text;

namespace Pr7Editor {
public static class SelfTest {
 static List<string> Results=new List<string>();
 static void Assert(bool condition,string message){if(!condition)throw new Exception("TEST: "+message);}
 static void Record(string s){Results.Add(s);}
 public static void Audit(string game,string output){var s=new Session(game);int good=0,surfaces=0;var failures=new List<string>();foreach(var a in s.Assets){string n=a.Name.ToLowerInvariant();if(!n.EndsWith(".rx2")||!(TextureCatalog.Includes("Caras",n)||TextureCatalog.Includes("Camisetas",n)||TextureCatalog.Includes("Botines",n)))continue;try{var ts=Texture.Parse(s.Read(a));if(ts.Count==0){failures.Add(a.Name+" | Sin superficies compatibles");continue;}good++;surfaces+=ts.Count;}catch(Exception e){failures.Add(a.Name+" | "+e.Message);}}
  File.WriteAllLines(output,new[]{"Recursos compatibles: "+good,"Superficies compatibles: "+surfaces,"Recursos protegidos/incompatibles: "+failures.Count}.Concat(failures),Encoding.UTF8);
 }
 internal static void MakeArchive(string path,Dictionary<string,byte[]> contents){var names=contents.Keys.ToArray();int size=16+names.Sum(n=>8+Encoding.UTF8.GetByteCount(n)+1);byte[] header=new byte[Bytes.Align(size,64)];Encoding.ASCII.GetBytes("BIG4").CopyTo(header,0);Bytes.BE(header,8,names.Length);Bytes.BE(header,12,header.Length);byte[] bh=new byte[16+20*names.Length];Encoding.ASCII.GetBytes("ViV4").CopyTo(bh,0);Buffer.BlockCopy(BitConverter.GetBytes(bh.Length),0,bh,4,4);Bytes.BE(bh,8,names.Length);Bytes.BE(bh,12,bh.Length);
  using(var m=new MemoryStream()){m.Write(header,0,header.Length);int p=16;for(int i=0;i<names.Length;i++){while(m.Position%64!=0)m.WriteByte(0);string name=names[i];byte[] packed=Bytes.LiteralPack(contents[name]);int offset=(int)m.Position;Bytes.BE(header,p,offset);Bytes.BE(header,p+4,packed.Length);Encoding.UTF8.GetBytes(name).CopyTo(header,p+8);p+=9+Encoding.UTF8.GetByteCount(name);Bytes.BE(bh,16+i*20,offset);Bytes.BE(bh,20+i*20,packed.Length);Bytes.BE(bh,24+i*20,contents[name].Length);Bytes.BE(bh,28+i*20,0xaabb0000u+(uint)i);Bytes.BE(bh,32+i*20,0xccdd0000u+(uint)i);m.Write(packed,0,packed.Length);}Buffer.BlockCopy(BitConverter.GetBytes((int)m.Length),0,header,4,4);m.Position=0;m.Write(header,0,header.Length);File.WriteAllBytes(path,m.ToArray());}File.WriteAllBytes(Path.ChangeExtension(path,".bh"),bh);
 }
 public static void Run(string output){Directory.CreateDirectory(output);string project=AppDomain.CurrentDomain.BaseDirectory;if(!Directory.Exists(Path.Combine(project,"analysis","modding-research")))project=Path.GetFullPath(Path.Combine(project,".."));string samples=Path.Combine(project,"analysis","modding-research","samples");byte[] db=File.ReadAllBytes(Path.Combine(samples,"fifa_ng_db.db")),meta=File.ReadAllBytes(Path.Combine(samples,"fifa_ng_db-meta.xml"));var d=new GameDatabase(db,meta);Assert(d.Tables.Count==90,"90 tablas/CRC");var players=d.Rows("players");Assert(players.Count==15188,"jugadores");int ri=players.FindIndex(r=>GameDatabase.Number(r,"playerid")==20801),si=players.FindIndex(r=>GameDatabase.Number(r,"playerid")==246);Assert(GameDatabase.Number(players[ri],"overallrating")==90,"media de referencia");
  byte[] unchanged=d.Serialize();Assert(unchanged.SequenceEqual(db),"DB sin cambios byte identica");var identity=new GameDatabase(unchanged,meta);var identityRows=identity.Rows("players");for(int row=0;row<players.Count;row++)foreach(string key in players[row].Keys)Assert(Object.Equals(players[row][key],identityRows[row][key]),"serializacion sin cambios");Record("DB: 90 tablas y todos los CRC; lectura de 15188 jugadores, serializacion sin cambios byte identica.");
  d.SetNumber("players",ri,"overallrating",93);d.SetNumber("players",si,"shoetypecode",108);long sleeve=GameDatabase.Number(players[si],"jerseysleevelengthcode");d.SetNumber("players",si,"jerseysleevelengthcode",1-sleeve);
  int nameRow=d.Rows("playernames").FindIndex(r=>GameDatabase.Number(r,"playerid")==20801);string newName="Cristiano pr7 ñ 中";d.SetName(nameRow,"firstname",newName);byte[] edited=d.Serialize();var reloaded=new GameDatabase(edited,meta);Assert(GameDatabase.Number(reloaded.Rows("players")[ri],"overallrating")==93,"guardar media");Assert(GameDatabase.Number(reloaded.Rows("players")[si],"shoetypecode")==108,"guardar botines");Assert((string)reloaded.Rows("playernames")[nameRow]["firstname"]==newName,"nombre Huffman Unicode");
  var baseline=new GameDatabase(db,meta);var before=baseline.Rows("players");var after=reloaded.Rows("players");for(int i=0;i<before.Count;i++)foreach(string key in before[i].Keys){if(i==ri&&key=="overallrating"||i==si&&(key=="shoetypecode"||key=="jerseysleevelengthcode"))continue;Assert(Object.Equals(before[i][key],after[i][key]),"campo vecino "+i+"/"+key);}
  var bn=baseline.Rows("playernames");var an=reloaded.Rows("playernames");for(int i=0;i<bn.Count;i++)foreach(string key in bn[i].Keys)if(!(i==nameRow&&key=="firstname"))Assert(Object.Equals(bn[i][key],an[i][key]),"nombre vecino");
  bool rejected=false;try{d.SetNumber("players",ri,"overallrating",100);}catch(ArgumentException){rejected=true;}Assert(rejected,"rechazar fuera de rango");Record("DB: media 93, botines, mangas y nombres Unicode guardados; campos vecinos intactos y rangos validados.");
  int surfaces=0;foreach(string path in Directory.GetFiles(samples,"*.rx2")){byte[] original=File.ReadAllBytes(path),copy=(byte[])original.Clone();var ts=Texture.Parse(copy);foreach(var t in ts){byte[] dds=t.Dds();t.ImportDds(dds);Assert(copy.SequenceEqual(original),"DDS exacto "+path+"/"+t.Section);var levels=new List<byte[]>();for(int l=0;l<t.Mips;l++){byte[] b=t.ReadLevel(l);for(int k=0;k<b.Length;k++)b[k]=(byte)((k*37+l*17+9)&255);levels.Add(b);t.WriteLevel(l,b);}for(int l=0;l<t.Mips;l++)Assert(t.ReadLevel(l).SequenceEqual(levels[l]),"mips independientes "+path+"/"+l);t.ImportDds(dds);Assert(copy.SequenceEqual(original),"restaurar todos los mips sin tocar otras secciones");
    string golden=Path.Combine(project,"analysis","modding-research","previews",Path.GetFileNameWithoutExtension(path)+".texture"+t.Section+".dds");if(File.Exists(golden)){byte[] g=File.ReadAllBytes(golden);Assert(t.ReadLevel(0).SequenceEqual(g.Skip(128)),"mip base vs exportador independiente");}surfaces++;}
  }Record("RX2: "+surfaces+" superficies; DDS de ida/vuelta exacto, todos los mipmaps independientes, otras secciones preservadas; mips base contrastados con exportador Python.");
  byte[] kit=File.ReadAllBytes(Path.Combine(samples,"kit_11_0_0.rx2"));var kt=Texture.Parse(kit).Where(t=>t.Format==18).OrderByDescending(t=>t.Width*t.Height).First();using(var b=new Bitmap(kt.Width,kt.Height)){using(var g=Graphics.FromImage(b))g.Clear(Color.FromArgb(255,240,20,15));b.Save(Path.Combine(output,"import-red.png"),ImageFormat.Png);}kt.ImportPng(Path.Combine(output,"import-red.png"));for(int l=0;l<kt.Mips;l++)using(var b=Codec.Decode(kt.ReadLevel(l),Math.Max(1,kt.Width>>l),Math.Max(1,kt.Height>>l),kt.Format)){Color c=b.GetPixel(0,0);Assert(c.R>200&&c.G<40&&c.B<40,"PNG regenero mip "+l);}Record("PNG: importacion y regeneracion de toda la cadena de mipmaps.");
  using(var transparent=new Bitmap(4,4,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(transparent))g.Clear(Color.Transparent);byte[] encoded=Codec.Encode(transparent,18);using(var decoded=Codec.Decode(encoded,4,4,18))Assert(decoded.GetPixel(0,0).A==0,"BC1 bloque completamente transparente");}Record("BC1: transparencia total preservada al importar PNG.");
  byte[] unchangedKit=(byte[])kit.Clone();bool bad=false;try{kt.ImportDds(new byte[128]);}catch(InvalidDataException){bad=true;}Assert(bad&&kit.SequenceEqual(unchangedKit),"rechazo DDS atomico");
  string work=Path.Combine(output,"work-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);MakeArchive(Path.Combine(work,"data0.big"),new Dictionary<string,byte[]>{{"data/db/fifa_ng_db.db",db},{"data/db/fifa_ng_db-meta.xml",meta}});MakeArchive(Path.Combine(work,"data3.big"),new Dictionary<string,byte[]>{{"data/sceneassets/kit/kit_11_0_0.rx2",File.ReadAllBytes(Path.Combine(samples,"kit_11_0_0.rx2"))}});
  var a0=new Archive(Path.Combine(work,"data0.big"));var a3=new Archive(Path.Combine(work,"data3.big"));var originals=Directory.GetFiles(work).ToDictionary(p=>p,p=>Bytes.Hash(p));var changes=new Dictionary<Asset,byte[]>{{a0.Entries[0],edited},{a3.Entries[0],kit}};string backup=Storage.SaveFiles(work,changes,Path.Combine(output,"backups"));var read=new Archive(Path.Combine(work,"data0.big"));new GameDatabase(read.Read(read.Entries[0]),meta);var ar=new Archive(Path.Combine(work,"data3.big"));Assert(ar.Read(ar.Entries[0]).SequenceEqual(kit),"archivo textura aplicado en copia");Assert(Bytes.UInt(File.ReadAllBytes(Path.Combine(work,"data0.bh")),28)==0xaabb0000u,"hash BH conservado");Storage.Restore(Path.Combine(backup,"respaldo.json"),work);foreach(var item in originals)Assert(Bytes.Hash(item.Key)==item.Value,"restauracion byte exacta");Record("BIG/BH: guardado multiarchivo verificado sobre copias, hashes BH conservados, respaldo y restauracion byte exacta.");
  var bh=File.ReadAllBytes(Path.Combine(work,"data0.bh"));byte[] damaged=(byte[])bh.Clone();Bytes.BE(damaged,16,999);File.WriteAllBytes(Path.Combine(work,"data0.bh"),damaged);bool fail=false;try{Storage.SaveFiles(work,new Dictionary<Asset,byte[]>{{new Archive(Path.Combine(work,"data0.big")).Entries[0],edited}},Path.Combine(output,"backups"));}catch(InvalidDataException){fail=true;}Assert(fail&&Bytes.Hash(Path.Combine(work,"data0.big"))==originals[Path.Combine(work,"data0.big")],"fallo antes de escritura");File.WriteAllBytes(Path.Combine(work,"data0.bh"),bh);Record("Errores: BH incompatible y DDS invalido rechazados sin cambiar el BIG/preview.");
  var expected=originals.ToDictionary(p=>Path.GetFileName(p.Key),p=>p.Value);string history=Path.Combine(output,"history-"+Guid.NewGuid().ToString("N"));
  var first=new Archive(Path.Combine(work,"data3.big"));Storage.SaveFiles(work,new Dictionary<Asset,byte[]>{{first.Entries[0],kit}},history);
  byte[] secondKit=(byte[])kit.Clone();secondKit[secondKit.Length-1]^=1;var second=new Archive(Path.Combine(work,"data3.big"));Storage.SaveFiles(work,new Dictionary<Asset,byte[]>{{second.Entries[0],secondKit}},history);
  var dbArchive=new Archive(Path.Combine(work,"data0.big"));byte[] untouched=dbArchive.Read(dbArchive.Entries[1]);Storage.SaveFiles(work,new Dictionary<Asset,byte[]>{{dbArchive.Entries[0],edited}},history);
  var ordered=new Archive(Path.Combine(work,"data0.big"));Assert(ordered.Read(ordered.Entries[1]).SequenceEqual(untouched),"recurso vecino preservado");
  byte[] bigBytes=File.ReadAllBytes(Path.Combine(work,"data0.big")),bhBytes=File.ReadAllBytes(Path.Combine(work,"data0.bh"));Assert(Bytes.UInt(bigBytes,16)<Bytes.UInt(bigBytes,16+9+Encoding.UTF8.GetByteCount(ordered.Entries[0].Name)),"orden de directorio conservado");Assert(Bytes.UInt(bhBytes,36)>Bytes.UInt(bhBytes,16),"BH en orden");
  var beforeFailure=Directory.GetFiles(work).ToDictionary(p=>p,p=>Bytes.Hash(p));bool missing=false;try{Originals.RestoreSet(work,Path.Combine(output,"missing-history"),expected);}catch(IOException){missing=true;}Assert(missing&&beforeFailure.All(p=>Bytes.Hash(p.Key)==p.Value),"restauracion incompleta rechazada antes de escribir");
  Assert(Originals.RestoreSet(work,history,expected)>0,"restauracion acumulativa");foreach(var p in originals)Assert(Bytes.Hash(p.Key)==p.Value,"original recuperado entre varios guardados");Record("Restaurar originales: historial con guardados separados/repetidos; todos los BIG/BH byte identicos. Sin respaldo completo no escribe nada. Orden BIG/BH y recurso vecino preservados.");
  string game=Path.Combine(project,"analysis","private","game");if(Directory.Exists(game)){var session=new Session(game);var rules=session.Appearance;foreach(var p in session.Db.Rows("players"))rules.Validate(p,new Dictionary<string,long>());var verified=new GameDatabase(Originals.ReadResource(session.DbAsset,session.Root,Path.Combine(project,"modding","backups")),session.Meta);var scholes=verified.Rows("players").First(p=>GameDatabase.Number(p,"playerid")==246);var change=new Dictionary<string,long>{{"shoetypecode",116},{"shoecolorcode1",1}};rules.Validate(scholes,change);Assert(change["shoecolorcode1"]==0,"Scholes 116 normaliza color inexistente 1 a 0");bool invalid=false;try{rules.Validate(scholes,new Dictionary<string,long>{{"shoetypecode",9999}});}catch(ArgumentException){invalid=true;}Assert(invalid,"botin inexistente rechazado");Record("Apariencia: 15188 jugadores originales validos; regresion Scholes botin116/color1 corregida a color0; IDs inexistentes rechazados.");}
  Results.AddRange(GrowthTests.Run(project,output));
  Results.AddRange(IndividualRestoreTests.Run(project,output));
  Results.AddRange(SingleOriginalTests.Run(output));
  File.WriteAllLines(Path.Combine(output,"resultados.txt"),Results,Encoding.UTF8);
 }
}
}
